"""Export untouched Solar Flare float32 masters and three-role source-bank policy.

--check compares retained inputs/generated bytes offline; no decoder or network runs.
Native dispatch, shuffle, cap-zero semantics and listener/bus mix remain unverified.
"""
from pathlib import Path
import hashlib
import json
import sys
import subprocess

sha = lambda b: hashlib.sha256(b).hexdigest()
graph_path = Path('docs/reference/leona-r-audio.json')
graph = json.loads(graph_path.read_text())
decoded = json.loads(Path('docs/reference/leona-r-audio-decoded.json').read_text())
assert decoded['sourceGraphSha256'] == sha(graph_path.read_bytes())
for item in graph['bankSources']:
    raw = Path(item['localPath']).read_bytes()
    assert len(raw) == item['bytes'] and sha(raw) == item['sha256']
xml = graph['parserXml']
assert sha(Path(xml['path']).read_bytes()) == xml['sha256']
for item in graph['media']:
    raw = (Path('.cache/leona-r-audio-media-v1-20261024') / f"{item['id']}.wem").read_bytes()
    assert len(raw) == item['bytes'] and sha(raw) == item['sha256']
nodes = {n['id']: n for n in graph['nodes']}


def parameter(identity, suffix, optional=False):
    found = [p for p in nodes[identity]['parameters'] if p[0].endswith('/' + suffix)]
    if optional and not found:
        return None
    assert len(found) == 1, (identity, suffix)
    return found[0][2]


def properties(identity):
    fields = nodes[identity]['parameters']
    result = {}
    for f in fields:
        if f[0].endswith('/pID'):
            key = f[3].split('[')[-1].removesuffix(']')
            value = next(p[2] for p in fields if p[0] == f[0][:-3] + 'pValue')
            assert key not in result
            result[key] = float(value)
    return result


events = {e['name']: e for e in graph['events']}
profile, outputs = {}, {}
policy_fields = ['eMode', 'eRandomMode', 'wAvoidRepeatCount', 'bResetPlayListAtEachPlay',
                 'bIsGlobal', 'bIsContinuous', '_bIsUsingWeight', 'u16MaxNumInstance',
                 'bKillNewest', 'sLoopCount', 'sLoopModMin', 'sLoopModMax', 'eTransitionMode']
for role, suffix, target, gain, cap, newest in [
    ('cast', 'LeonaSolarFlare_OnCast', 2441, -7, 2, 0),
    ('area', 'LeonaSolarFlare_buffactivate', 653116368, -5, 0, 0),
    ('impact', 'LeonaSolarFlare_hit', 2443, -1, 2, 0),
]:
    event = events['Play_sfx_Leona_' + suffix]
    assert len(event['actions']) == 1
    action = event['actions'][0]
    assert action['target'] == target and properties(action['id']) == {}
    assert int(parameter(action['id'], 'eFadeCurve')) == 4
    authored = properties(target)
    assert authored['MakeUpGain'] == gain
    pitch = authored.get('Pitch', 0)
    assert pitch == 0
    assert int(parameter(target, 'DirectParentID')) == 2440
    policy = {k: int(v) for k in policy_fields if (v := parameter(target, k, True)) is not None}
    assert policy['u16MaxNumInstance'] == cap and policy['bKillNewest'] == newest
    direct = nodes[target]['type'] == 'CAkSound'
    if direct:
        assert role == 'area'
        sounds = [target]
    else:
        assert nodes[target]['type'] == 'CAkRanSeqCntr'
        assert {k: policy[k] for k in policy if k not in ['u16MaxNumInstance', 'bKillNewest']} == dict(
            eMode=0, eRandomMode=1, wAvoidRepeatCount=0, bResetPlayListAtEachPlay=1,
            bIsGlobal=1, bIsContinuous=0, _bIsUsingWeight=0, sLoopCount=1,
            sLoopModMin=0, sLoopModMax=0, eTransitionMode=0)
        count = int(parameter(target, 'ulPlayListItem'))
        assert count == 4
        sounds = [int(parameter(target, f'AkPlaylistItem:{i}/ulPlayID')) for i in range(count)]
        assert all(int(parameter(target, f'AkPlaylistItem:{i}/weight')) == 50000 for i in range(count))
    variants = []
    for sound in sounds:
        sound_properties = properties(sound)
        assert 'Loop' not in sound_properties
        identity = int(parameter(sound, 'sourceID'))
        m = next(m for m in decoded['media'] if m['id'] == identity)
        assert m['sampleRate'] == 44100 and m['channels'] == 1
        assert m['decoderMetadata']['loopingInfo'] is None
        raw = (Path('.cache/leona-r-audio-decoded-v2-20261024') / f'{identity}.wav').read_bytes()
        assert sha(raw) == m['wavSha256']
        url = f'assets/audio/leona-r-{identity}.wav'
        outputs['public/' + url] = raw
        variants.append(dict(id=identity, soundId=sound, url=url, sha256=m['wavSha256'],
                             pcmSha256=m['pcmSha256'], frames=m['frames'], sampleRate=m['sampleRate'],
                             channels=m['channels'], durationSeconds=m['durationSeconds'], peak=m['peak'],
                             authoredProperties=sound_properties))
    assert {v['id'] for v in variants} == set(action['affectedMediaIds'])
    stop = None
    profile[role] = dict(eventId=event['id'], actionId=action['id'], targetId=target,
                         targetType=nodes[target]['type'], gainDb=gain, pitchCents=pitch,
                         pitchProvenance='authored Pitch property' if 'Pitch' in authored else 'local zero for absent Pitch; native default unverified',
                         fadeInSeconds=0, fadeInProvenance='local zero for absent play TransitionTime; native default unverified',
                         authoredProperties=authored, playProperties=properties(action['id']),
                         policy=policy, capZeroPolicy='local unlimited; native cap-zero semantics unverified' if cap == 0 else None,
                         stop=stop, variants=variants,
                         maxDurationSeconds=max(v['durationSeconds'] for v in variants))
assert properties(2440) == {} and int(parameter(2440, 'DirectParentID')) == 695650395
assert properties(695650395) == {'Priority': 60, 'AttenuationID': 339248780}
assert int(parameter(695650395, 'OverrideBusId')) == 1259461568
assert graph['unresolvedHierarchyIds'] == [1259461568]
assert int(parameter(339248780, 'eScaling')) == 2
assert int(parameter(339248780, 'curveToUse[0]')) == 0
profile['attenuation'] = dict(id=339248780, scaling=2,
    points=[dict(distance=float(parameter(339248780, f'AkRTPCGraphPoint:{i}/From')),
                 storedValue=float(parameter(339248780, f'AkRTPCGraphPoint:{i}/To')),
                 interpolation=int(parameter(339248780, f'AkRTPCGraphPoint:{i}/Interp'))) for i in range(6)],
    unresolvedOutputBusId=1259461568)
profile['limits'] = ['Native R dispatch, global shuffle/random sequence, listening, listener/bus mix and rendering parity remain unverified.',
                     'Audio masters remain finite and untouched; pitch belongs to runtime playback, not exported PCM.',
                     'Zero cap is locally unlimited. Missing pitch/play-transition/stop-delay fields use explicit local zero defaults.']
assert graph['stopAudit']['matchingStopActions'] == [] and graph['stopAudit']['declaredStopEvents'] == []
source = ('// Generated by tools/assets/export-leona-r-audio.py.\n'
          '// Untouched finite float32 masters; native dispatch/mix remain unverified.\n'
          + 'export const LEONA_R_AUDIO = ' + json.dumps(profile, indent=2) + ' as const;\n')
outputs['src/content/leona-r-audio.ts'] = subprocess.check_output(
    ['node_modules/.bin/prettier', '--stdin-filepath', 'src/content/leona-r-audio.ts'],
    input=source.encode())
for file, raw in outputs.items():
    path = Path(file)
    if '--check' in sys.argv:
        assert path.read_bytes() == raw, file
    else:
        if path.exists():
            assert path.read_bytes() == raw, 'Refuse to replace changed output: ' + file
        else:
            path.write_bytes(raw)
print(json.dumps(dict(result='passed', checkOnly='--check' in sys.argv, events=len(events), roles=3,
                      media=len(decoded['media']), shippedBytes=sum(len(b) for p,b in outputs.items() if p.endswith('.wav')))))
